#include "web_config.h"
#include "imu.h"
#include "esp_http_server.h"
#include "esp_wifi.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_log.h"
#include "cJSON.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#ifndef CONFIG_WHOOPY_AP_SSID
#define CONFIG_WHOOPY_AP_SSID "Whoopy-Setup"
#endif
#ifndef CONFIG_WHOOPY_AP_PASSWORD
#define CONFIG_WHOOPY_AP_PASSWORD "whoopy-setup-2026"
#endif
static drone_config_t*cfg;static live_status_t*st;static volatile bool*cal_req,*is_armed;static httpd_handle_t server;static const char*TAG="webcfg";
static const char page[]="<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'><title>Whoopy setup</title><style>body{font:16px system-ui;max-width:900px;margin:auto;padding:16px;background:#101820;color:#eee}section{background:#1e2b36;margin:12px 0;padding:16px;border-radius:12px}input,select{width:7em;margin:4px;padding:5px}button{padding:10px;margin:4px}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>Whoopy flight controller</h1><section><h2>Live status</h2><pre id=s>Loading</pre></section><section><h2>Flight settings</h2><div id=f></div><p>Rate PID uses gyro/setpoint in °/s. Kp unit is PWM fraction per (°/s); Ki is PWM fraction per integrated rate error (°); Kd is PWM fraction per (°/s²). Output is saturated before mixing. Motor output is capped at the configured fraction of full PWM. Complementary alpha weights gyro prediction (0.90–0.999). Changes apply temporarily until saved.</p><button onclick=apply()>Apply temporarily</button><button onclick=save()>Save to flash</button><button onclick=defaults()>Restore defaults</button><button onclick=cal()>Calibrate gyro</button><p id=m></p></section><script>let c;async function load(){let r=await fetch('/api/config');c=await r.json();let f=document.querySelector('#f');f.innerHTML='';['roll','pitch','yaw'].forEach(a=>f.innerHTML+=`<h3>${a} rate PID</h3>${['kp','ki','kd'].map(k=>`${k} <input id=${a+k} type=number step=0.0001 value=${c[a][k]}>`).join('')}`);f.innerHTML+=`<p>Max stabilized angle ° <input id=angle type=number value=${c.max_angle_deg}></p><p>Max rate °/s <input id=rate type=number value=${c.max_rate_dps}></p><p>Complementary alpha <input id=alpha type=number step=.001 value=${c.complementary_alpha}></p><p>Failsafe timeout ms <input id=timeout type=number value=${c.failsafe_ms}></p><p>Maximum motor PWM fraction <input id=motor type=number step=.01 value=${c.max_motor_output}></p><p>Mode <select id=acro><option value=false>Stabilized</option><option value=true>Acro / rate</option></select></p>`;document.querySelector('#acro').value=String(c.acro)}async function status(){document.querySelector('#s').textContent=JSON.stringify(await(await fetch('/api/status')).json(),null,2)}async function apply(){['roll','pitch','yaw'].forEach(a=>['kp','ki','kd'].forEach(k=>c[a][k]=Number(document.querySelector('#'+a+k).value)));c.max_angle_deg=Number(document.querySelector('#angle').value);c.max_rate_dps=Number(document.querySelector('#rate').value);c.complementary_alpha=Number(document.querySelector('#alpha').value);c.failsafe_ms=Number(document.querySelector('#timeout').value);c.max_motor_output=Number(document.querySelector('#motor').value);c.acro=document.querySelector('#acro').value==='true';let r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(c)});document.querySelector('#m').textContent=await r.text()}async function save(){let r=await fetch('/api/save',{method:'POST'});document.querySelector('#m').textContent=await r.text()}async function defaults(){let r=await fetch('/api/defaults',{method:'POST'});document.querySelector('#m').textContent=await r.text();await load()}async function cal(){let r=await fetch('/api/calibrate',{method:'POST'});document.querySelector('#m').textContent=await r.text()}load();status();setInterval(status,1000)</script>";
static esp_err_t root(httpd_req_t*r){httpd_resp_set_type(r,"text/html");return httpd_resp_send(r,page,HTTPD_RESP_USE_STRLEN);}
static esp_err_t status_get(httpd_req_t*r){char b[720];snprintf(b,sizeof b,"{\"state\":\"%s\",\"armed\":%s,\"calibrating\":%s,\"calibration_status\":\"%s\",\"imu_ok\":%s,\"radio_ok\":%s,\"battery_available\":false,\"packet_age_ms\":%lu,\"loop_us\":%lu,\"control_hz\":250,\"attitude_deg\":[%.2f,%.2f],\"gyro_dps\":[%.2f,%.2f,%.2f],\"controls\":[%.3f,%.3f,%.3f,%.3f],\"motors\":[%.3f,%.3f,%.3f,%.3f]}",st->state,*is_armed?"true":"false",st->calibrating?"true":"false",st->calibration_status?st->calibration_status:"not run",st->imu_ok?"true":"false",st->radio_ok?"true":"false",(unsigned long)st->packet_age_ms,(unsigned long)st->loop_us,st->roll,st->pitch,st->gx,st->gy,st->gz,st->controls[0],st->controls[1],st->controls[2],st->controls[3],st->motors[0],st->motors[1],st->motors[2],st->motors[3]);httpd_resp_set_type(r,"application/json");return httpd_resp_sendstr(r,b);}
static esp_err_t cfg_get(httpd_req_t*r){char b[640];snprintf(b,sizeof b,"{\"roll\":{\"kp\":%.6f,\"ki\":%.6f,\"kd\":%.6f},\"pitch\":{\"kp\":%.6f,\"ki\":%.6f,\"kd\":%.6f},\"yaw\":{\"kp\":%.6f,\"ki\":%.6f,\"kd\":%.6f},\"max_angle_deg\":%.1f,\"max_rate_dps\":%.1f,\"max_motor_output\":%.2f,\"complementary_alpha\":%.3f,\"failsafe_ms\":%u,\"acro\":%s}",cfg->roll.kp,cfg->roll.ki,cfg->roll.kd,cfg->pitch.kp,cfg->pitch.ki,cfg->pitch.kd,cfg->yaw.kp,cfg->yaw.ki,cfg->yaw.kd,cfg->max_angle_deg,cfg->max_rate_dps,cfg->max_motor_output,cfg->complementary_alpha,cfg->failsafe_ms,cfg->acro?"true":"false");httpd_resp_set_type(r,"application/json");return httpd_resp_sendstr(r,b);}
static bool num(cJSON*o,const char*k,float*x){cJSON*v=cJSON_GetObjectItemCaseSensitive(o,k);if(!cJSON_IsNumber(v))return false;*x=(float)v->valuedouble;return true;}
static esp_err_t cfg_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Configuration changes require DISARMED state");}if(r->content_len>1024)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Request too large");char*b=calloc(1,r->content_len+1);if(!b)return ESP_ERR_NO_MEM;size_t got=0;while(got<r->content_len){int n=httpd_req_recv(r,b+got,r->content_len-got);if(n<=0){free(b);return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Incomplete request body");}got+=(size_t)n;}cJSON*j=cJSON_Parse(b);free(b);if(!j)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Invalid JSON");drone_config_t next=*cfg;cJSON*o;bool ok=true;const char*names[]={"roll","pitch","yaw"};whoopy_pid_cfg_t*ps[]={&next.roll,&next.pitch,&next.yaw};for(int i=0;i<3&&ok;i++){o=cJSON_GetObjectItemCaseSensitive(j,names[i]);ok=cJSON_IsObject(o)&&num(o,"kp",&ps[i]->kp)&&num(o,"ki",&ps[i]->ki)&&num(o,"kd",&ps[i]->kd);}ok=ok&&num(j,"max_angle_deg",&next.max_angle_deg)&&num(j,"max_rate_dps",&next.max_rate_dps)&&num(j,"max_motor_output",&next.max_motor_output)&&num(j,"complementary_alpha",&next.complementary_alpha);cJSON*to=cJSON_GetObjectItemCaseSensitive(j,"failsafe_ms");cJSON*acro=cJSON_GetObjectItemCaseSensitive(j,"acro");ok=ok&&cJSON_IsNumber(to)&&floor(to->valuedouble)==to->valuedouble&&to->valueint>=100&&to->valueint<=1000&&cJSON_IsBool(acro);if(ok){next.failsafe_ms=(uint16_t)to->valueint;next.acro=cJSON_IsTrue(acro);}cJSON_Delete(j);if(!ok||!config_valid(&next))return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Missing or out-of-range PID/config value");*cfg=next;imu_set_filter_alpha(cfg->complementary_alpha);return httpd_resp_sendstr(r,"Applied temporarily. Use Save to flash to persist.");}
static esp_err_t save_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Disarm first");}esp_err_t e=config_save(cfg);return httpd_resp_sendstr(r,e==ESP_OK?"Saved":"Save failed");}
static esp_err_t defaults_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Disarm first");}config_defaults(cfg);imu_set_filter_alpha(cfg->complementary_alpha);return httpd_resp_sendstr(r,"Defaults applied in RAM; save explicitly to persist");}
static esp_err_t cal_post(httpd_req_t*r){if(strcmp(st->state,"DISARMED")!=0){httpd_resp_set_status(r,"409 Conflict");return httpd_resp_sendstr(r,"Disarm first");}*cal_req=true;return httpd_resp_sendstr(r,"Calibration queued; status is shown on dashboard");}
void web_config_start(drone_config_t*c,live_status_t*s,volatile bool*cr,volatile bool*a){cfg=c;st=s;cal_req=cr;is_armed=a;size_t ssid_len=strlen(CONFIG_WHOOPY_AP_SSID),pass_len=strlen(CONFIG_WHOOPY_AP_PASSWORD);if(ssid_len==0||ssid_len>32||pass_len<8||pass_len>63){ESP_LOGE(TAG,"AP settings invalid; use SSID 1-32 chars and WPA2 password 8-63 chars");return;}ESP_ERROR_CHECK(esp_netif_init());ESP_ERROR_CHECK(esp_event_loop_create_default());esp_netif_create_default_wifi_ap();wifi_init_config_t w=WIFI_INIT_CONFIG_DEFAULT();ESP_ERROR_CHECK(esp_wifi_init(&w));wifi_config_t ap={.ap={.ssid_len=0,.channel=6,.max_connection=2,.authmode=WIFI_AUTH_WPA2_PSK}};strlcpy((char*)ap.ap.ssid,CONFIG_WHOOPY_AP_SSID,sizeof(ap.ap.ssid));strlcpy((char*)ap.ap.password,CONFIG_WHOOPY_AP_PASSWORD,sizeof(ap.ap.password));ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP,&ap));ESP_ERROR_CHECK(esp_wifi_start());httpd_config_t hc=HTTPD_DEFAULT_CONFIG();hc.max_uri_handlers=8;ESP_ERROR_CHECK(httpd_start(&server,&hc));httpd_uri_t u[]={{"/",HTTP_GET,root},{"/api/status",HTTP_GET,status_get},{"/api/config",HTTP_GET,cfg_get},{"/api/config",HTTP_POST,cfg_post},{"/api/save",HTTP_POST,save_post},{"/api/defaults",HTTP_POST,defaults_post},{"/api/calibrate",HTTP_POST,cal_post}};for(unsigned i=0;i<sizeof(u)/sizeof(u[0]);i++)httpd_register_uri_handler(server,&u[i]);ESP_LOGI(TAG,"AP started; password intentionally not logged");}
